import { createEnvironmentUI } from './environment-ui.js';
import { LAYERS } from './wmts.js';
import { analyzeRoute, routePoints } from './route.js';
import { createUniverse } from './journey.js';
const $=id=>document.getElementById(id);
let environmentUI=null;
let universe=null, ready=false, state={mode:'galaxy',travelling:false,mapMode:false}, selection=null, currentLayer='visual';
const chapters={galaxy:['01 — A COSMIC PERSPECTIVE','The Milky Way.','A hundred billion possibilities.<br>One world waiting to be explored.','MILKY WAY / ORION ARM','NASA / JPL-CALTECH · ARTIST’S CONCEPT'],solar:['02 — OUR STELLAR NEIGHBOURHOOD','Our solar system.','Eight worlds from sunlit Mercury to distant Neptune.<br>Towards a different kind of horizon.','SOLAR SYSTEM / PLANETARY SYSTEM','ILLUSTRATIVE ORBITS · DISTANCES & SIZES NOT TO SCALE'],mars:['03 — THE RED PLANET','Anywhere on Mars.','Ancient valleys, volcanic plains and silent craters.<br>Find the place your next chapter begins.','MARS / ORBITAL EXPLORER','SURFACE MOSAIC · SOLAR SYSTEM SCOPE / NASA-BASED']};
const moonDescriptions={phobos:'Phobos — cratered terrain and the deep Stickney impact basin. Drag to inspect its irregular shape.',deimos:'Deimos — the smaller moon, with a softer outline and a smoother, dust-covered surface.'};
document.querySelectorAll('[data-moon]').forEach(button=>button.onclick=()=>universe?.inspectMoon(button.dataset.moon||null));
function renderState(s){
 $('moon-panel').hidden=s.mode!=='mars'||s.travelling||s.mapMode;
 document.querySelectorAll('[data-moon]').forEach(button=>button.setAttribute('aria-pressed',String((button.dataset.moon||null)===s.selectedMoon)));
 $('moon-description').textContent=moonDescriptions[s.selectedMoon]||'Two small, irregular worlds. Select a moon for a close-up.';
 document.body.dataset.moon=s.selectedMoon||'';
$('map-scale').hidden=!s.mapMode;state=s;const stage=s.mapMode?'map':s.mode;document.body.dataset.stage=stage;const text=chapters[s.mode];$('location').textContent=s.mapMode?'MARS / GLOBAL SURFACE ATLAS':text[3];$('eyebrow').textContent=text[0];$('title').textContent=text[1];$('description').innerHTML=text[2];$('stage-meta').textContent=s.mapMode?(currentLayer==='climate'?'MCD 6.2 · SEASONAL MODEL, NOT LIVE WEATHER':currentLayer==='visual'?'ENHANCED VISUAL MOSAIC · SOLAR SYSTEM SCOPE':currentLayer==='nasa'?'VIKING MOSAIC · NASA / USGS':(currentLayer==='thermal'?'USGS COG · ':currentLayer==='ctx'?'CALTECH / ESRI · ':'NASA TREK WMTS · ')+LAYERS[currentLayer].name.toUpperCase()):(s.mode==='mars'?(currentLayer==='climate'?'MCD 6.2 · SEASONAL MODEL, NOT LIVE WEATHER':currentLayer==='visual'?'ENHANCED VISUAL MOSAIC · SOLAR SYSTEM SCOPE':currentLayer==='nasa'?'VIKING MOSAIC · NASA / USGS':'NASA TREK WMTS · '+LAYERS[currentLayer].name.toUpperCase()):text[4]);$('story').hidden=s.mapMode;$('map-ui').hidden=!s.mapMode;$('map-readout').hidden=!s.mapMode;$('planet-panel').hidden=s.mode!=='mars'||s.travelling||s.mapMode;$('view-tools').hidden=s.travelling;$('explore-panel').hidden=s.mode==='mars'||s.travelling||!s.ready;$('galaxy-actions').hidden=s.mode!=='galaxy';$('solar-actions').hidden=s.mode!=='solar';$('explore-eyebrow').textContent=s.mode==='galaxy'?'GALACTIC OBSERVATORY':'PLANETARY OBSERVATORY';$('explore-title').textContent=s.mode==='galaxy'?'Choose your perspective.':'Explore our solar system.';$('body-select').value=s.selectedBody||'overview';$('flight-controls').hidden=!s.travelling;$('skip').hidden=s.mode==='mars'&&!s.travelling;$('begin').hidden=s.travelling;$('begin').disabled=!s.ready;$('begin').querySelector('span').textContent=s.mode==='mars'?'Open surface atlas':s.mode==='solar'?'Continue to Mars':'Continue to solar system';$('hint').textContent=s.mode==='mars'?'DRAG TO ROTATE · SCROLL TO EXPLORE':'JOURNEY PAUSED · PRESS ANY KEY TO CONTINUE';$('hint').hidden=s.travelling;$('unfold').hidden=s.mode!=='mars'||s.travelling;$('object-label').hidden=s.mode!=='galaxy'||s.travelling||!$('galaxy-labels').checked;$('pause-flight').textContent=s.paused?'▷ Resume':'Ⅱ Pause';$('pause-flight').setAttribute('aria-label',s.paused?'Resume journey':'Pause journey');$('spin').hidden=s.mapMode||s.mode!=='mars'||!!s.selectedMoon;$('toggle-map').hidden=s.mode!=='mars';$('spin').textContent=s.spin?'Ⅱ':'▷';$('spin').setAttribute('aria-label',s.spin?'Pause rotation':'Resume rotation');$('spin').setAttribute('aria-pressed',String(!s.spin));$('toggle-map').textContent=s.mapMode?'3D GLOBE':'2D MAP';document.querySelectorAll('[data-stop]').forEach(b=>b.classList.toggle('active',!s.mapMode&&((s.mode==='galaxy'&&b.dataset.stop==='0')||(s.mode==='solar'&&b.dataset.stop==='0.53')||(s.mode==='mars'&&b.dataset.stop==='1'))));if(s.selectedMoon){$('title').textContent=s.selectedMoon==='phobos'?'Phobos.':'Deimos.';$('eyebrow').textContent='03 — THE MOONS OF MARS';$('description').textContent=s.selectedMoon==='phobos'?'A battered, grooved companion.':'A small world, softened by dust.';$('stage-meta').textContent='3D MODEL & SURFACE TEXTURE · NASA / JPL-CALTECH';$('planet-panel').hidden=true;}$('map-stop').classList.toggle('active',s.mapMode);$('timeline-fill').style.width=s.mapMode?'100%':`${s.progress*66.666}%`;}
function show(html){$('dialog-content').innerHTML=html;$('dialog').showModal();}
$('close-dialog').onclick=()=>$('dialog').close();$('dialog').addEventListener('click',e=>{if(e.target!==$('dialog'))return;const r=$('dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('dialog').close();});
$('credits').onclick=()=>show(`<div class="eyebrow">SCIENCE, DESIGN & OPEN DATA</div><h2>From the stars to the surface.</h2><p>ARES is an evolving exploration atlas. This release connects a cinematic view of the Milky Way, the solar system, an interactive Mars globe and a flat surface atlas in one continuous graphics scene.</p><ul class="source-list"><li>Milky Way: <a href="https://science.nasa.gov/photojournal/our-milky-way-gets-a-makeover-artist-concept/" target="_blank" rel="noopener">NASA / JPL-Caltech, PIA10748</a> — an artist’s concept, not a photograph taken outside our galaxy.</li><li>Planet textures and enhanced Mars mosaic: <a href="https://edu.solarsystemscope.com/textures/" target="_blank" rel="noopener">Solar System Scope</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>. Based on NASA imagery; color-adjusted visual maps, with some unmapped areas filled illustratively.</li><li>Viking map layer: <a href="https://science.nasa.gov/3d-resources/mars/" target="_blank" rel="noopener">NASA / JPL-Caltech / USGS</a>.</li><li>CTX V01: <a href="https://murray-lab.caltech.edu/CTX/V01/TilePages/" target="_blank" rel="noopener">Caltech Murray Lab</a> / Esri / NASA / JPL / MSSS. Semi-controlled mosaic, ~5 m per pixel.</li><li>THEMIS Night IR: <a href="https://registry.opendata.aws/nasa-usgs-themis-mosaics/" target="_blank" rel="noopener">NASA / USGS controlled mosaics</a>, CC0. Streamed from original Cloud Optimized GeoTIFFs using GeoTIFF.js (MIT).</li><li>Archive: <a href="https://images.nasa.gov/" target="_blank" rel="noopener">NASA Image and Video Library</a>, fetched from its public API.</li><li>Mars moons: <a href="https://science.nasa.gov/resource/phobos-mars-moon-3d-model/" target="_blank" rel="noopener">Phobos</a> and <a href="https://science.nasa.gov/resource/deimos-mars-moon-3d-model/" target="_blank" rel="noopener">Deimos</a> — NASA/JPL-Caltech 3D models with original embedded textures. Display sizes and orbit distances are illustrative; orbital motion pauses for close-up inspection.</li><li>Graphics: Three.js, MIT license. One renderer and one Mars mesh from arrival to the flat projection.</li></ul><p class="notice">Distances, sizes, orbital positions and travel speed in the cinematic are illustrative. The atlas streams Caltech CTX V01 through Esri and MOLA through NASA Trek WMTS. Route samples expose pixel coverage; RGB values do not encode calibrated elevation or certify safety.</p><p>Independent project. Not affiliated with NASA.</p>`);
function start(){if(!ready)return;if(state.mode==='mars')universe.unfold(true);else universe.travel(state.mode==='galaxy'?.53:1,state.mode==='galaxy'?10:7);}
$('begin').onclick=start;
 const bodyDescriptions={overview:'Select a world to explore its atmosphere, surface or rings.',sun:'A textured photosphere surrounded by a soft luminous corona.',mercury:'Explore the cratered landscape across the day–night boundary.',venus:'A world concealed beneath a dense, luminous cloud deck.',earth:'Blue oceans, continents, moving clouds and the Moon orbiting nearby.',moon:'Earth’s natural satellite — dark basaltic maria and ancient cratered highlands.',mars:'Inspect the red planet here, then continue to open its surface atlas.',jupiter:'Follow the bands and swirling cloud structures of the giant planet.',saturn:'Explore the subtle cloud bands and the finely structured ring system.',uranus:'An ice giant tilted nearly onto its side, encircled by faint vertical rings and a pale cyan haze.',neptune:'The outermost major planet — a deep azure ice giant swept by supersonic winds.'};
 $('body-select').onchange=e=>{universe?.inspectBody(e.target.value);$('body-description').textContent=bodyDescriptions[e.target.value];};
 $('solar-overview').onclick=()=>{universe?.inspectBody('overview');$('body-description').textContent=bodyDescriptions.overview;};
 $('galaxy-top').onclick=()=>universe?.galaxyView(true);$('galaxy-oblique').onclick=()=>universe?.galaxyView(false);
 $('galaxy-labels').onchange=()=>renderState(state);$('show-orbits').onchange=e=>universe?.setOrbits(e.target.checked);$('unfold').onclick=()=>universe?.unfold(true);$('toggle-map').onclick=()=>universe?.unfold(!state.mapMode);$('map-stop').onclick=()=>universe?.unfold(true);$('skip').onclick=()=>universe?.skip();$('replay').onclick=()=>universe?.travel(0,3);$('home').onclick=e=>{e.preventDefault();universe?.travel(0,3);};$('pause-flight').onclick=()=>universe?.pause();$('spin').onclick=()=>universe?.spin();$('zoom-in').onclick=()=>universe?.zoom(.8);$('zoom-out').onclick=()=>universe?.zoom(1.25);$('reset').onclick=()=>universe?.reset();
$('terrain-map').onclick=()=>document.querySelector('input[name="layer"][value="ctx"]').click();
$('grid').onchange=e=>universe?.setGrid(e.target.checked);document.querySelectorAll('input[name="layer"]').forEach(input=>input.onchange=()=>{currentLayer=input.value;universe?.setLayer(input.value);renderState(state);});
for(const b of document.querySelectorAll('[data-stop]'))b.onclick=()=>universe?.travel(Number(b.dataset.stop),3.5);
function selectRegion(button){const lat=Number(button.dataset.lat),lon=Number(button.dataset.lon),name=button.childNodes[0].textContent.trim();universe?.select(lat,lon,name,true);}
for(const b of document.querySelectorAll('.region'))b.onclick=()=>selectRegion(b);
$('regions').onclick=()=>{universe?.unfold(true);};
$('mobile-region').onchange=e=>{if(!e.target.value)return;const [lat,lon]=e.target.value.split(',').map(Number);universe?.select(lat,lon,e.target.selectedOptions[0].textContent,true);};
const TERRAIN_LAB_URL=(typeof localStorage!=='undefined'&&localStorage.getItem('ares-terrain-lab-url'))||'http://127.0.0.1:4174';
function terrainLabHref(point){const q=new URLSearchParams({lat:point.lat.toFixed(4),lon:point.lon.toFixed(4),span:'3',name:point.name||'Mars Selection'});return `${TERRAIN_LAB_URL}/?${q}`;}
function renderSelection(point){selection=point;environmentUI?.select(point);$('route-start').disabled=false;$('route-end').disabled=false;const href=terrainLabHref(point);if($('terrain-lab-link'))$('terrain-lab-link').href=href;$('selection').innerHTML='<div class="eyebrow">SELECTED LOCATION</div>';const p=document.createElement('p');p.textContent=point.name;const strong=document.createElement('strong');strong.textContent=`${Math.abs(point.lat).toFixed(3)}° ${point.lat>=0?'N':'S'}\n${Math.abs(point.lon).toFixed(3)}° ${point.lon>=0?'E':'W'}`;strong.style.whiteSpace='pre-line';const copy=document.createElement('button');copy.textContent='Copy coordinates ↗';copy.onclick=async()=>{try{await navigator.clipboard.writeText(`${point.lat.toFixed(5)}, ${point.lon.toFixed(5)}`);copy.textContent='Copied ✓';}catch{copy.textContent=`${point.lat.toFixed(3)}, ${point.lon.toFixed(3)}`;}};const open3d=document.createElement('a');open3d.href=href;open3d.textContent='Open 3D Terrain Lab ↗';open3d.style.cssText='display:inline-block;margin-top:6px;padding:7px 11px;border:1px solid rgba(239,214,171,.45);border-radius:999px;color:#efd6ab;text-decoration:none;font-size:.78rem;';$('selection').append(p,strong,copy,open3d);}
let archiveItems=null,archiveLoading=false;
async function archive(){show('<div class="eyebrow">NASA IMAGE AND VIDEO LIBRARY</div><h2>Through the eyes of our missions.</h2><p>Archival images from the open NASA API. Not live surface observations.</p><div id="archive-items" class="archive-grid"><p>Connecting to NASA…</p></div>');if(archiveItems){renderArchive(archiveItems);return;}if(archiveLoading)return;archiveLoading=true;try{const r=await fetch('https://images-api.nasa.gov/search?q=mars%20surface&media_type=image&page_size=6',{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error();const d=await r.json();archiveItems=(d.collection?.items||[]).filter(i=>i.links?.some(l=>l.rel==='preview')).slice(0,6);if(!archiveItems.length)throw Error();renderArchive(archiveItems);}catch{const box=$('archive-items');if(box){box.innerHTML='<p class="loading-error">The archive is unavailable. <button id="retry-archive">Try again ↻</button></p>';$('retry-archive').onclick=archive;}}finally{archiveLoading=false;}}
function renderArchive(items){const box=$('archive-items');if(!box)return;box.replaceChildren();for(const item of items){const d=item.data[0],a=document.createElement('a');a.href='https://images.nasa.gov/details/'+encodeURIComponent(d.nasa_id);a.target='_blank';a.rel='noopener';const img=document.createElement('img');img.src=item.links.find(l=>l.rel==='preview').href;img.alt=d.title;img.loading='lazy';const title=document.createElement('h3');title.textContent=d.title+' ↗';const date=document.createElement('small');date.textContent=(d.date_created||'').slice(0,10)+' / NASA';a.append(img,title,date);box.append(a);}}
$('archive').onclick=archive;
document.addEventListener('keydown',e=>{if(!ready||e.repeat||$('dialog').open||e.ctrlKey||e.metaKey||e.altKey)return;const editable=['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName);if(editable)return;if(e.key==='Escape'){if(state.mapMode)universe.unfold(false);else if(state.travelling)universe.skip();return;}if(e.key==='Tab'||['Shift','Control','Alt','Meta','CapsLock'].includes(e.key))return;if(e.target.closest('button,a')&&(e.key==='Enter'||e.key===' '))return;if(state.mode!=='mars'&&!state.travelling){e.preventDefault();start();return;}if((e.key==='+'||e.key==='=')&&state.mode==='mars'){e.preventDefault();universe.zoom(.8);}if(e.key==='-'&&state.mode==='mars'){e.preventDefault();universe.zoom(1.25);}});
try{universe=await createUniverse($('universe'),{orion:({x,y})=>{const label=$('object-label');const left=Math.round(x)+'px',top=Math.round(y)+'px';if(label.style.left!==left)label.style.left=left;if(label.style.top!==top)label.style.top=top;},loading:(n,total)=>{$('load-text').textContent=`Preparing imagery · ${n} / ${total}`;},tiles:renderTiles,scale:renderScale,state:renderState,progress:p=>{$('timeline-fill').style.width=`${p*66.666}%`;$('flight-status').textContent=p<.35?'Entering the Orion Arm':p<.82?'Approaching our solar system':'Settling into Mars orbit';},select:renderSelection,error:message=>{$('fallback').hidden=false;$('fallback').querySelector('p').textContent=message;}});ready=true;$('loader').hidden=true;$('begin').disabled=false;universe.setGrid(true);if(location.hash==='#map')universe.unfold(true);else if(location.hash==='#mars')universe.skip();const initQ=new URLSearchParams(location.search);if(initQ.has('lat')&&initQ.has('lon')){const qLat=Number(initQ.get('lat')),qLon=Number(initQ.get('lon'));if(Number.isFinite(qLat)&&Number.isFinite(qLon)){if(location.hash!=='#map')universe.skip();universe.select(qLat,qLon,initQ.get('name')||'Selected Mars Location',location.hash==='#map');}}}catch(error){$('loader').hidden=true;$('fallback').hidden=false;$('fallback').querySelector('p').textContent=error.message||'3D requires WebGL. Open the global mosaic below.';console.error(error);}

function renderScale({metresPerPixel,latitude}){const horizontal=metresPerPixel*Math.max(.001,Math.cos(latitude*Math.PI/180)),raw=horizontal*100,power=10**Math.floor(Math.log10(raw)),length=[1,2,5,10].map(v=>v*power).filter(v=>v<=raw).at(-1);$('scale-label').textContent=length>=1000?(length/1000).toLocaleString('en')+' km':length.toLocaleString('en')+' m';$('scale-bar').style.width=(length/horizontal)+'px';}
function renderTiles(info){
 $('map-detail-source').textContent=info.baseKey?(info.status==='detail-loading'?'Loading CTX close-up…':info.status==='error'?'CTX close-up unavailable · retry': 'Close-up: CTX V01 · '+(info.metresPerPixel?.toFixed(1)??'?')+' m/px'):(info.status==='local'?'Overview · zoom for CTX detail':info.key==='ctx'?'CTX V01 · streamed surface imagery':'');
 $('retry-tiles').hidden=info.status==='local';
 if(info.status==='local'){$('tile-status').textContent=(info.key==='visual'?'Original Mars mosaic · local 8K imagery':'Viking mosaic · local imagery')+' · CTX close-ups load automatically as you zoom.';return;}
 if(info.status==='detail-loading'){$('tile-status').textContent=LAYERS[info.key].name+' · Loading visible detail…'+(info.baseKey?' · Automatic close-up for selected overview':'');return;}
 $('tile-status').textContent=info.status==='loading'?'Loading source metadata and tiles…':info.status==='error'?'Source tiles unavailable. Check connection and retry.':LAYERS[info.key].name+(info.baseKey?' · Automatic close-up':'')+' · level '+info.level+' · '+info.loaded+'/'+info.total+' tiles · '+(info.metresPerPixel>=1000?(info.metresPerPixel/1000).toFixed(2)+' km':info.metresPerPixel.toFixed(1)+' m')+'/px at equator'+(info.sourceLimit?' · Source resolution limit reached':'')+(info.budgetLimited?' · Detail limited by display memory budget':'')+(info.status==='partial'?' · missing tiles':info.status==='streaming'?' · loading remaining tiles…':'')+(['thermal','minerals'].includes(info.key)?' · Hatched areas: no source data.':'');
}
$('retry-tiles').onclick=()=>universe?.setLayer(currentLayer);
let routeStart=null,routeEnd=null,analysisEpoch=0,routeReport=null;
function invalidateRoute(){analysisEpoch++;environmentUI?.route(routeStart,routeEnd);routeReport=null;$('route-export').disabled=true;$('route-analyze').disabled=!(routeStart&&routeEnd);$('route-result').textContent='Safety: unknown. Calibrated terrain data required.';$('route-points').textContent=[routeStart?'Start: '+routeStart.lat.toFixed(3)+', '+routeStart.lon.toFixed(3):'Choose start',routeEnd?'End: '+routeEnd.lat.toFixed(3)+', '+routeEnd.lon.toFixed(3):'Choose destination'].join(' / ');try{universe?.updateRoute(routeStart&&routeEnd?routePoints(routeStart,routeEnd):[]);}catch(e){universe?.updateRoute([]);$('route-result').textContent=e.message;$('route-analyze').disabled=true;}}
$('route-start').onclick=()=>{routeStart=selection&&{...selection};invalidateRoute();};$('route-end').onclick=()=>{routeEnd=selection&&{...selection};invalidateRoute();};$('route-clear').onclick=()=>{routeStart=routeEnd=null;invalidateRoute();};
$('route-analyze').onclick=async()=>{if(!routeStart||!routeEnd)return;routeReport=null;$('route-export').disabled=true;const epoch=++analysisEpoch;$('route-analyze').disabled=true;$('route-result').textContent='Reading CTX + MOLA pixels along the route…';try{const report=await analyzeRoute(universe.trek,routeStart,routeEnd,()=>epoch===analysisEpoch);if(!report||epoch!==analysisEpoch)return;routeReport={...report,environment:environmentUI?.report()??null,start:routeStart,end:routeEnd,source:'Caltech / Esri CTX V01 and NASA Trek MOLA rendered imagery',sampledAt:new Date().toISOString()};$('route-export').disabled=false;const valid=report.samples.find(p=>p.ctx?.valid&&p.mola?.valid);$('route-result').textContent=report.length.toFixed(2)+' km · '+report.covered+'/'+report.total+' samples have opaque pixels in both layers. Safety: UNKNOWN. '+(valid?'Example CTX RGB: '+valid.ctx.rgba.slice(0,3).join('/')+'; MOLA RGB: '+valid.mola.rgba.slice(0,3).join('/')+'. ':'')+'Fixed sampling level ≤7; coverage between samples and opaque no-data pixels are not verified. '+report.reason;}catch(e){if(epoch===analysisEpoch)$('route-result').textContent='Analysis unavailable: '+e.message;}finally{if(epoch===analysisEpoch)$('route-analyze').disabled=false;}};

$('route-export').onclick=()=>{if(!routeReport)return;const url=URL.createObjectURL(new Blob([JSON.stringify({...routeReport,environment:environmentUI?.report()??null},null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='mars-route-samples.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};

if(universe)environmentUI=createEnvironmentUI({map(canvas){currentLayer='climate';document.querySelectorAll('input[name="layer"]').forEach(i=>i.checked=false);universe.setEnvironmentMap(canvas);renderState(state);},select(point){universe.select(point.lat,point.lon,point.name,true);}});


$('rover-selected').onclick=e=>{if(!routeStart||!routeEnd)return;e.preventDefault();const q=new URLSearchParams({startLat:routeStart.lat,startLon:routeStart.lon,goalLat:routeEnd.lat,goalLon:routeEnd.lon});location.href='rover.html?'+q;};
